"""Snap clock times to a step and label the spans."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

def _check_step(step: int) -> None:
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"step must divide 60: {step!r}")

def _snap(minutes: int, step: int) -> int:
    """Nearest multiple of step. A tie rounds up."""
    return (minutes + step // 2) // step * step

def _snap_span(span: Span, step: int) -> Span:
    start = _snap(span.start, step)
    end = _snap(span.end, step)
    if start >= end:
        text = format_span(span)
        raise ValueError(f"{text} is empty at step {step}")
    return Span(start, end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def label_rounded_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Snap ends to the nearest step and label each span."""
    _check_step(step)
    snapped = (_snap_span(span, step) for span in spans)
    return [_label(item) for item in snapped]

