# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import label_rounded_spans

class LabelTests(unittest.TestCase):
    def test_rounds_to_quarter_hours(self):
        self.assertEqual(
            label_rounded_spans([Span(547, 1028)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        self.assertEqual(
            label_rounded_spans([Span(545, 600)], 10),
            ["09:10-10:00 (0h 50m)"]
        )

    def test_exact_times_are_unchanged(self):
        self.assertEqual(
            label_rounded_spans([Span(540, 1020)], 30),
            ["09:00-17:00 (8h 0m)"]
        )

    def test_step_of_one_keeps_minutes(self):
        self.assertEqual(
            label_rounded_spans([Span(541, 1019)], 1),
            ["09:01-16:59 (7h 58m)"]
        )

    def test_step_of_an_hour(self):
        self.assertEqual(
            label_rounded_spans([Span(560, 1060)], 60),
            ["09:00-18:00 (9h 0m)"]
        )

    def test_keeps_order_and_count(self):
        spans = [Span(540, 600), Span(780, 1020)]
        self.assertEqual(
            label_rounded_spans(spans, 15),
            ["09:00-10:00 (1h 0m)", "13:00-17:00 (4h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120, 2.5):
            with self.assertRaises(ValueError):
                label_rounded_spans([Span(540, 600)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(1436, 1440)], 15)
